package uk.ac.ravensbourne.casevault.report;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import uk.ac.ravensbourne.casevault.audit.*; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.*;
/** Generates plaintext client summaries from authorised, client-visible case data only. */
@Service public class ReportService { private final CaseAccessService access; private final CaseRepository cases; private final CaseNoteRepository notes; private final RemediationActionRepository actions; private final ReportRepository reports; private final UserAccountRepository users; private final Redactor redactor; private final AuditService audit; public ReportService(CaseAccessService a,CaseRepository c,CaseNoteRepository n,RemediationActionRepository r,ReportRepository p,UserAccountRepository u,Redactor d,AuditService au){access=a;cases=c;notes=n;actions=r;reports=p;users=u;redactor=d;audit=au;} @Transactional public ReportRecord generate(UserPrincipal p,UUID caseId){CaseRecord c=access.requireView(p,caseId);if(!new AccessPolicy().canGenerateReport(p,c,cases.existsAssignment(caseId,p.id())))throw new CaseNotFoundException();int version=reports.findFirstByCaseRecordIdOrderByVersionDesc(caseId).map(x->x.getVersion()+1).orElse(1);StringBuilder b=new StringBuilder("Case summary\nTitle: ").append(redactor.redact(c.getTitle())).append("\nStatus: ").append(c.getStatus()).append("\nFindings:\n");notes.findByCaseRecordIdAndClientVisibleTrue(caseId).forEach(n->b.append("- ").append(redactor.redact(n.getBody())).append('\n'));b.append("Remediation:\n");actions.findByCaseRecordId(caseId).forEach(a->b.append("- ").append(redactor.redact(a.getDescription())).append(" [").append(a.getStatus()).append("]\n"));ReportRecord r=reports.save(new ReportRecord(UUID.randomUUID(),c,c.getOrganisation(),users.findById(p.id()).orElseThrow(),version,b.toString()));r.submit();audit.record(p,AuditEventType.REPORT_APPROVED,"REPORT",r.getId(),"report-generated");return r;} public ReportRecord approvedForClient(UserPrincipal p,UUID caseId,UUID reportId){CaseRecord c=access.requireView(p,caseId);ReportRecord r=reports.findByIdAndCaseRecordId(reportId,caseId).orElseThrow(CaseNotFoundException::new);if(Role.CLIENT_USER.name().equals(p.role())&&r.getStatus()!=ReportStatus.APPROVED)throw new CaseNotFoundException();audit.record(p,"REPORT_DOWNLOADED","REPORT",reportId,"report-downloaded");return r;} }
